  "mapa.titulo": { es: "Mapa AION 2: recolección y localizaciones", en: "AION 2 map: gathering and locations", fr: "Carte AION 2 : récolte et lieux", de: "AION 2 Karte: Sammeln und Orte", pt: "Mapa do AION 2: recolha e localização", ru: "Карта AION 2: сбор и расположение", ko: "AION 2 맵: 모임 및 위치", ja: "AION 2の地図:集まり、場所" },
  "mapa.sub": { es: "Busca rubí, odyle, zaif, cubos ocultos, mascotas y jefes en Verteron, Altgard, Eltnen, Morheim y el Abismo.", en: "Find ruby, odyle, zaif, hidden cubes, pets and bosses in Verteron, Altgard, Eltnen, Morheim and the Abyss.", fr: "Trouvez rubis, odyle, zaif, cubes cachés, familiers et bosses à Verteron, Altgard, Eltnen, Morheim et l’Abysse.", de: "Finden Sie Rubin, Odyle, Zaif, versteckte Würfel, Haustiere und Bosse in Verteron, Altgard, Eltnen, Morheim und dem Abyss.", pt: "Encontre rubi, odyle, zaif, cubos escondidos, animais de estimação e chefes em Verteron, Altgard, Eltnen, Morheim e o Abismo.", ru: "Найдите рубин, одил, заиф, скрытые кубики, домашних животных и боссов в Вертероне, Альтгарде, Эльтнене, Морхайме и Бездне.", ko: "찾기 루비, odyle, zaif, 숨겨진 큐브, 애완 동물과 보스 Verteron, Altgard, Eltnen, Morheim 및 Abysss.", ja: "Verteron、Altgard、Eltnen、Morheim、Abyssのルビー、ダイル、zaif、隠しキューブ、ペット、上司を見つける。" },
  "mapa.buscar": { es: "Buscar", en: "Search", fr: "Rechercher", de: "Suchen", pt: "Pesquisar", ru: "Поиск", ko: "검색", ja: "検索" },
  "mapa.buscar_ph": { es: "Ej. rubí, odyle, zaif, cubo…", en: "E.g. ruby, odyle, zaif, cube…", fr: "Ej. rubí, odyle, zaif, cubo…", de: "z. B. Rubin, Odyle, Zaif, Würfel...", pt: "Por exemplo, rubi, odyle, zaif, cubo...", ru: "Например, рубин, одила, заиф, куб...", ko: "E.g. ruby, odyle, 자프, 큐브 ...", ja: "E.g. ruby, ダイル, zaif, キューブ..." },
