  "mapa.filtros": { es: "Filtros", en: "Filters", fr: "Filtres", de: "Filter", pt: "Filtros", ru: "Фильтры", ko: "필터링", ja: "フィルター" },
  "mapa.marcadores": { es: "{n} marcadores en el mapa", en: "{n} markers on the map", fr: "{n} markers on the map", de: "{n} Marker auf der Karte", pt: "Marcadores {n} no mapa", ru: "Маркеры на карте", ko: "{n} 지도에 표시", ja: "地図上の {n} マーカー" },
  "mapa.error": { es: "No se ha podido cargar el mapa.", en: "Could not load the map.", fr: "Impossible de charger la carte.", de: "Konnte die Karte nicht laden.", pt: "Não foi possível carregar o mapa.", ru: "Не удалось загрузить карту.", ko: "지도를로드 할 수 없습니다.", ja: "地図をロードできません。" },
  "mapa.nota": { es: "Spawns del cliente AION 2 (recolección, mascotas, rastros…). Cubos de Altgard: 59 grupos / 1371 puntos del datamine. Eltnen/Morheim casi sin mascotas en el cliente global. Fan site, sin relación con NCSOFT.", en: "AION 2 client spawns (gathering, pets, traces…). Altgard cubes: 59 groups / 1371 spots from datamine. Eltnen/Morheim barely have pets in the global client. Fan site, not affiliated with NCSOFT.", fr: "Spawns du client AION 2 (récolte, familiers, traces…). Cubes Altgard : 59 groupes / 1371 points issus du datamine. Eltnen/Morheim ont presque aucun familier dans le client global. Site de fans, non affilié à NCSOFT.", de: "AION 2 Client Spawns (Sammlung, Haustiere, Spuren ...). Altgard-Würfel: 59 Gruppen / 1371 Spots aus Datamine. Eltnen/Morheim haben kaum Haustiere im globalen Kunden. Fan-Website, nicht mit NCSOFT verbunden.", pt: "AION 2 cliente desova (ajuntamento, animais de estimação, vestígios ...). Altgard cubos: 59 grupos / 1371 manchas de datamine. Eltnen/Morheim mal tem animais de estimação no cliente global. Site de fãs, não afiliado à NCSOFT.", ru: "Клиентские нерестилища AION 2 (сбор, домашние животные, следы...). Альтгардские кубы: 59 групп / 1371 пятен от датамина. У Эльтнена/Морхайма практически нет домашних животных. Фан-сайт, не связанный с NCSOFT.", ko: "AION 2 클라이언트 스페인 (가벼운, 애완 동물, 추적 ...). Altgard cubes: 59 그룹 / 1371 자료의 명소. Eltnen/Morheim Barely는 글로벌 클라이언트에서 애완 동물을 가지고 있습니다. 팬 사이트, NCSOFT와 제휴하지.", ja: "AION 2 クライアントスプーン (ギャザリング、ペット、トレース...)。 Altgard キューブ: 59 グループ/ 1371 スポット から datamine. Eltnen/Morheim は、世界中のクライアントにペットを飼っています。 NCSOFTと提携しないファンサイト。" },
  "mapa.fuente": { es: "Spawns · cliente + datamine (fan)", en: "Spawns · client + datamine (fan)", fr: "Spawns · cliente + datamine (fan)", de: "Spawns · Client + Datamine (Fan)", pt: "Spawns · client + datamine (fan)", ru: "Spawns · клиент + датамин (фанат)", ko: "Spawns · 클라이언트 + datamine (팬)", ja: "スパン・クライアント+データマイニング(ファン)" },
  "mapa.tip_ruby": { es: "Prueba «rubí» o «ruby» con Recolección activada. También odyle, zaif, cubos ocultos y mascotas.", en: "Try “ruby” with Gathering on. Also odyle, zaif, hidden cubes and pets.", fr: "Essayez « ruby » avec Gathering activé. Aussi odyle, zaif, cubes cachés et familiers.", de: "Versuchen Sie \"Ruby\" mit Gathering on. Auch Odyle, Zaif, versteckte Würfel und Haustiere.", pt: "Tente \"ruby\" com a reunião. Também odyle, zaif, cubos escondidos e animais de estimação.", ru: "Попробуй \"Руби\" со Сбором. Также одила, заиф, скрытые кубики и домашние животные.", ko: "“ruby”를 사용해 보세요. 또한 odyle, 자프, 숨겨진 큐브와 애완 동물.", ja: "ガザリングで「ルビー」をお試しください。 また、ダイル、シーフ、隠しキューブ、ペット。" },
  "region.eu": { es: "Europa (EU)", en: "Europe (EU)", fr: "Europe (EU)", de: "Europa (EU)", pt: "Europa (UE)", ru: "Европа (ЕС)", ko: "유럽 (EU)", ja: "ヨーロッパ(EU)" },
  "region.naw": { es: "Norteamérica Oeste (NAW)", en: "North America West (NAW)", fr: "Amérique du Nord Ouest (NAW)", de: "North America West (NAW)", pt: "América do Norte Ocidental (NAW)", ru: "Северная Америка Запад (NAW)", ko: "북아메리카 서쪽 (NAW)", ja: "北アメリカ西(NAW)" },
  "region.nae": { es: "Norteamérica Este (NAE)", en: "North America East (NAE)", fr: "Amérique du Nord Est (NAE)", de: "North America East (NAE)", pt: "América do Norte Leste (NAE)", ru: "Северная Америка Восток (NAE)", ko: "북미 동쪽 (NAE)", ja: "北アメリカ東(NAE)" },
  "region.la": { es: "Latinoamérica (LA)", en: "Latin America (LA)", fr: "Amérique latine (LA)", de: "Lateinamerika (LA)", pt: "América Latina (LA)", ru: "Латинская Америка (LA)", ko: "라틴 아메리카 (LA)", ja: "ラテンアメリカ (LA)" },
