  "tops.elige_servidor": { es: "Elige un servidor", en: "Choose a server", fr: "Choisissez un serveur", de: "Wählen Sie einen Server", pt: "Escolha um servidor", ru: "Выберите сервер", ko: "서버 선택", ja: "サーバーを選択" },
  "tops.orden": { es: "Ordenar por", en: "Sort by", fr: "Trier par", de: "Sortieren nach", pt: "Ordenar por", ru: "Сортировать по", ko: "정렬 기준", ja: "並び替え" },
