  "tops.resultado": { es: "Mostrando {n} · {total} en este filtro", en: "Showing {n} · {total} in this filter", fr: "Affichage de {n} · {total} dans ce filtre", de: "Zeigen {n} · {Gesamt} in diesem Filter", pt: "Mostrando {n} · {total} neste filtro", ru: "Показать {n} · {total} в этом фильтре", ko: "표시 {n} · {total} 이 필터에", ja: "このフィルタで {n} · {total} を表示" },
  "tops.vacio": { es: "Aún no hay nadie en este filtro. Espía builds y volverán a aparecer aquí.", en: "No one in this filter yet. Spy some builds and they will show up here.", fr: "Personne dans ce filtre pour l’instant. Espionnez des builds et elles apparaîtront ici.", de: "Noch niemand in diesem Filter. Spionieren Sie einige Builds und sie werden hier auftauchen.", pt: "Ninguém neste filtro ainda. Espiem alguns prédios e eles aparecerão aqui.", ru: "В этом фильтре пока никого нет. Шпионские постройки, и они появятся здесь.", ko: "이 필터에 하나도 없습니다. 일부 빌드를 스파이하고 그들은 여기에 표시됩니다.", ja: "このフィルターの1つはまだありません。 いくつかのビルドをスパイすると、ここで表示されます。" },
  "tops.ir_espia": { es: "← Ir a Espía Builds", en: "← Go to Spy Builds", fr: "← Aller à Espion Builds", de: "← Gehen Sie zu Spy Builds", pt: "← Ir para construções de espião", ru: "Оригинальное название: Go to Spy Builds", ko: "← 스파이 빌드 이동", ja: "← スパイビルドに行く" },
