  "dae.no_enlaza": { es: "Ese nodo no enlaza con ninguno activo.", en: "That node isn't linked to an active one.", fr: "Ce nœud n’est pas lié à un nœud actif.", de: "Dieser Knoten ist nicht mit einem aktiven verknüpft.", pt: "Esse nó não está ligado a um activo.", ru: "Этот узел не связан с активным.", ko: "노드는 Active One에 연결되지 않습니다.", ja: "ノードがアクティブなノードにリンクされていない。" },
  "dae.ayuda_ver": { es: "Pasa el ratón por un nodo para ver su efecto. Los tableros se desbloquean por nivel; Ariel usa cristales de conquista y Azphel de batalla.", en: "Hover a node to see its effect. Boards unlock by level; Ariel uses conquest crystals and Azphel battle crystals.", fr: "Survolez un nœud pour voir son effet. Les tableaux se débloquent par niveau ; Ariel utilise des cristaux de conquête et Azphel des cristaux de bataille.", de: "Bewegen Sie einen Knoten, um seine Wirkung zu sehen. Bretter werden nach Leveln freigeschaltet; Ariel verwendet Eroberungskristalle und Azphel-Kampfkristalle.", pt: "Hover um nó para ver o seu efeito. Placas desbloquear por nível; Ariel usa cristais de conquista e Azphel cristais de batalha.", ru: "Наведите узел, чтобы увидеть его эффект. Доски разблокируются по уровню; Ариэль использует кристаллы завоевания и боевые кристаллы Азфеля.", ko: "노드를 통해 효과를 볼 수 있습니다. 레벨에 의해 잠금 해제 보드; 아리엘은 정복 크리스탈과 아젤 전투 크리스탈을 사용합니다.", ja: "ノードをフーバーして、その効果を確認します。 ボードはレベルによってロックを解除します。アリエルは征服の水晶およびアズフェルの戦いの水晶を使用します。" },
  "dae.ayuda_editar": { es: "Clic en un nodo enlazado (brillante) para activarlo; clic en uno activo para quitarlo junto con los que dependan de él.", en: "Click a linked (glowing) node to activate it; click an active one to remove it along with the nodes that depend on it.", fr: "Cliquez un nœud lié (lumineux) pour l’activer ; cliquez un nœud actif pour le retirer avec ceux qui en dépendent.", de: "Klicken Sie auf einen verknüpften (leuchtenden) Knoten, um ihn zu aktivieren; Klicken Sie auf einen aktiven, um ihn zusammen mit den Knoten, die davon abhängen, zu entfernen.", pt: "Clique em um nó vinculado para ativá-lo; clique em um ativo para removê-lo junto com os nós que dependem dele.", ru: "Нажмите на связанный (светящийся) узел, чтобы активировать его; нажмите на активный, чтобы удалить его вместе с узлами, которые зависят от него.", ko: "연결된 (glowing) 노드를 클릭하여 활성화하십시오. 노드와 함께 제거하려면 활성 하나를 클릭합니다.", ja: "接続された (glowing) ノードをクリックし、アクティブ ノードをクリックし、それに依存するノードと共に削除します。" },
  "barra.titulo_barra": { es: "Barra de habilidades", en: "Skill hotbar", fr: "Barre de compétences", de: "Geschickliche Hotbar", pt: "Barra quente de habilidade", ru: "Навык горячего бара", ko: "기술 핫 바", ja: "スキルホットバー" },
  "barra.titulo_macro": { es: "Macro", en: "Macro", fr: "Macro", de: "Makro", pt: "Macro", ru: "Макро", ko: "제품정보", ja: "ログイン" },
  "barra.vacia": { es: "Este preset aún no tiene barra.", en: "This preset has no hotbar yet.", fr: "Ce preset n’a pas encore de barre.", de: "Dieses Preset hat noch keine Hotbar.", pt: "Esta predefinição ainda não tem barra quente.", ru: "У этого набора пока нет горячей панели.", ko: "이 미리 설정은 핫 바가 없습니다.", ja: "このプリセットにはホットバーはありません。" },
  "barra.sin_macro": { es: "Sin macro: todo se pulsa a mano.", en: "No macro: everything is pressed manually.", fr: "Pas de macro : tout se joue à la main.", de: "Kein Makro: Alles wird manuell gedrückt.", pt: "Nenhuma macro: tudo é pressionado manualmente.", ru: "Никакого макроса: все нажимается вручную.", ko: "매크로가 없습니다: 모든 것은 수동으로 눌러집니다.", ja: "マクロなし:すべてが手動で押されます。" },
  "barra.sin_presets": { es: "Esta build no tiene barra ni macro.", en: "This build has no hotbar or macro.", fr: "Cette build n’a ni barre ni macro.", de: "Dieser Build hat keine Hotbar oder Makro.", pt: "Esta compilação não tem barra quente ou macro.", ru: "У этой сборки нет горячей панели или макроса.", ko: "이 빌드는 Hotbar 또는 매크로가 없습니다.", ja: "このビルドには、ホットバーやマクロはありません。" },
  "barra.empieza": { es: "Crea un preset o carga la plantilla de tu clase para empezar.", en: "Create a preset or load your class template to start.", fr: "Créez un preset ou chargez le modèle de classe pour commencer.", de: "Erstellen Sie eine Voreinstellung oder laden Sie Ihre Klassenvorlage zum Starten.", pt: "Crie um modelo predefinido ou carregue a sua classe para iniciar.", ru: "Создайте предустановленный или загрузите шаблон класса, чтобы начать.", ko: "미리 설정하거나 클래스 템플릿을로드하십시오.", ja: "プリセットを作成するか、クラステンプレートをロードして開始します。" },
  "barra.nota_prioridad": {
    es: "Cada tecla apila hasta 4 habilidades: la de abajo (fila 0) tiene más prioridad y el juego lanza la primera que no esté en enfriamiento.",
    en: "Each key stacks up to 4 skills: the bottom one (row 0) has top priority and the game fires the first one off cooldown.", fr: "Chaque touche empile jusqu’à 4 compétences : celle du bas (rang 0) a la priorité et le jeu lance la première disponible.", de: "Jeder Schlüssel stapelt bis zu 4 Fähigkeiten: Die unterste (Zeile 0) hat oberste Priorität und das Spiel feuert die erste ab.", pt: "Cada chave empilha até 4 habilidades: a inferior (linha 0) tem prioridade máxima e o jogo dispara o primeiro fora de resfriamento.", ru: "Каждый ключ содержит до 4 навыков: нижняя часть (ряд 0) имеет высший приоритет, и игра запускает первую.", ko: "각 키 스택 최대 4 기술: 하단 하나 (로 0) 최고 우선 순위와 게임 화재 첫 번째 재사용 대기 시간.", ja: "各キーは最大4スキルを積み上げます。一番下の1(row 0)は最優先であり、ゲームは最初の1オフクールダウンを発射します。"
  },
  "barra.uso_macro": { es: "Macro", en: "Macro", fr: "Macro", de: "Makro", pt: "Macro", ru: "Макро", ko: "제품정보", ja: "ログイン" },
