  "barra.uso_ambas": { es: "Macro y mano", en: "Macro & manual", fr: "Macro & manuel", de: "Makro- und Handbuch", pt: "Macro & manual", ru: "Macro & Manual", ko: "매크로 및 매뉴얼", ja: "マクロ&マニュアル" },
