  "barra.bucle": { es: "Se repite mientras mantengas la tecla", en: "Repeats while you hold the key", fr: "Se répète tant que vous maintenez la touche", de: "Wiederholt, während Sie den Schlüssel halten", pt: "Repeti enquanto segura a tecla", ru: "Повторяйте, пока держите ключ", ko: "열쇠를 붙드는 동안 반복", ja: "キーを押しながら繰り返します" },
  "barra.editar": { es: "Editar preset", en: "Edit preset", fr: "Modifier le preset", de: "Preset bearbeiten", pt: "Editar a predefinição", ru: "Редактировать preset", ko: "사전 설정", ja: "プリセットの編集" },
