  "barra.quitar_preset": { es: "Borrar preset", en: "Delete preset", fr: "Supprimer le preset", de: "Preset löschen", pt: "Apagar a predefinição", ru: "Удалить preset", ko: "사전 설정", ja: "プリセットの削除" },
  "barra.quitar_preset_conf": { es: "¿Borrar este preset con su barra y su macro?", en: "Delete this preset with its hotbar and macro?", fr: "Supprimer ce preset avec sa barre et sa macro ?", de: "Löschen Sie dieses Preset mit seiner Hotbar und Makro?", pt: "Apagar esta predefinição com a sua barra quente e macro?", ru: "Удалите этот предустановленный с его горячей панелью и макросом?", ko: "이 프리셋을 Hotbar와 매크로로 삭제?", ja: "ホットバーとマクロでこのプリセットを削除しますか?" },
  "barra.nuevo_preset": { es: "Preset", en: "Preset", fr: "Preset", de: "Preset", pt: "Predefinição", ru: "Предустановленный", ko: "기타 제품", ja: "プリセット" },
  "barra.preset": { es: "Preset", en: "Preset", fr: "Preset", de: "Preset", pt: "Predefinição", ru: "Предустановленный", ko: "기타 제품", ja: "プリセット" },
  "barra.plantilla": { es: "Cargar plantilla de la clase", en: "Load class template", fr: "Charger le modèle de classe", de: "Muster für die Belastungsklasse", pt: "Carregar modelo de classe", ru: "Шаблон класса нагрузки", ko: "로드 클래스 템플릿", ja: "ロードクラステンプレート" },
  "barra.plantilla_conf": { es: "Esto sustituye la barra y la macro de este preset. ¿Seguir?", en: "This replaces this preset's hotbar and macro. Continue?", fr: "Cela remplace la barre et la macro de ce preset. Continuer ?", de: "Dies ersetzt die Hotbar und das Makro dieses Presets. Weiter so?", pt: "Isto substitui a barra e macro deste ajuste predefinido. Continuar?", ru: "Это заменяет горячую панель и макрос этого набора. Продолжай?", ko: "이 프리셋의 핫 바와 매크로를 대체합니다. 계속?", ja: "このプリセットのホットバーとマクロを置き換えます。 お問い合わせ" },
  "barra.plantilla_ok": { es: "Plantilla cargada (build de referencia)", en: "Template loaded (reference build)", fr: "Modèle chargé (build de référence)", de: "Beladene Vorlage (Referenzaufbau)", pt: "Modelo carregado (compilação de referências)", ru: "Загруженный шаблон (справочная сборка)", ko: "템플릿로드 (reference build)", ja: "テンプレートの読み込み(リファレンスビルド)" },
