  "barra.fila_0": { es: "Fila 0: máxima prioridad", en: "Row 0: top priority", fr: "Fila 0: máxima prioridad", de: "Zeile 0: oberste Priorität", pt: "Linha 0: prioridade máxima", ru: "Уровень 0: главный приоритет", ko: "행 0: 최고 우선권", ja: "列 0: 最優先" },
