  "barra.nueva_linea": { es: "Añadir tecla", en: "Add key", fr: "Añadir tecla", de: "Schlüssel hinzufügen", pt: "Adicionar chave", ru: "Добавить ключ", ko: "키 추가", ja: "キーを追加" },
  "barra.tecla_macro": { es: "Tecla de la macro", en: "Macro key", fr: "Tecla de la macro", de: "Makroschlüssel", pt: "Chave da macro", ru: "Макро ключ", ko: "매크로 키", ja: "マクロキー" },
