  "barra.notas": { es: "Notas (cuándo pulsar cada cosa, cancelaciones…)", en: "Notes (when to press what, cancels…)", fr: "pases (when à press what, Annulers…)", de: "Notizen (wann drücken, was, annulliert ...)", pt: "Notas (quando pressionar o quê, cancela...)", ru: "Заметки (когда нажимать что, отменяет...)", ko: "메모 (그것을 눌러, 취소 ...)", ja: "ノート(何かを押すとき、キャンセル...)" },
  "barra.buscar": { es: "Buscar habilidad…", en: "Search skill…", fr: "Rechercher compétence…", de: "Suchfertigkeit...", pt: "Capacidade de pesquisa...", ru: "Поисковый навык...", ko: "검색 기술...", ja: "スキル検索" },
  "barra.vaciar": { es: "Vaciar hueco", en: "Clear slot", fr: "Vaciar hueco", de: "Freiraum", pt: "Limpar o espaço", ru: "Чистый слот", ko: "명확한 구멍", ja: "明確なスロット" },
  "barra.como": { es: "Cómo se configura en el juego", en: "How to set it up in game", fr: "How à set it up dans Jeu", de: "Wie man es im Spiel einrichtet", pt: "Como configurá-lo no jogo", ru: "Как настроить его в игре", ko: "게임에서 설정하는 방법", ja: "ゲームで設定する方法" },
  "barra.paso1": { es: "Asigna la tecla de macro en Ajustes → Teclas → General → Juego → Macro (viene sin asignar).", en: "Bind the macro key in Settings → Key settings → General → Gameplay → Macro (unbound by default).", fr: "Asigna la tecla de macro en Ajustes → Teclas → Général → Jeu → Macro (viene sans asignar).", de: "Binden Sie den Makroschlüssel in Einstellungen → Schlüsseleinstellungen → Allgemein → Gameplay → Makro (standardmäßig ungebunden).", pt: "Amarre a chave macro em Configurações → Configurações de teclas → Geral → Jogo → Macro (não ligado por padrão).", ru: "Свяжите макро-ключ в настройках → Ключевые настройки → Общие → Геймплей → Макро (несвязанный по умолчанию).", ko: "설정 → 키 설정 → 일반 → 게임 플레이 → 매크로 (기본값으로 실행)의 매크로 키.", ja: "マクロキーを [設定] → [キー設定] → [全般] → [Gameplay → [マクロ] (デフォルトでアンバウンド) に結合します。" },
  "barra.paso2": { es: "En la barra, apila hasta 4 habilidades por tecla: abajo la más importante, arriba las de relleno sin enfriamiento.", en: "On the hotbar, stack up to 4 skills per key: the most important at the bottom, no-cooldown fillers on top.", fr: "En la barra, apila jusqu’à 4 habilidades por tecla: abajo la plus importante, arriba las de relleno sans enfriamiento.", de: "Auf der Hotbar stapeln Sie bis zu 4 Fähigkeiten pro Schlüssel: die wichtigsten unten, keine Cooldown-Füller oben.", pt: "Na barra quente, empilhar até 4 habilidades por chave: o mais importante na parte inferior, sem refrigeradores em cima.", ru: "На горячей панели сложите до 4 навыков на ключ: самые важные внизу, наполнители без охлаждения сверху.", ko: "Hotbar에, 열쇠 당 4개의 기술까지 겹쳐 쌓이십시오: 바닥, 정상에 no-cooldown 충전물에 가장 중요한.", ja: "ホットバーでは、キーごとに最大4つのスキルを積み重ねます。一番重要なのは、トップのクールダウンフィラーです。" },
  "barra.paso3": { es: "Abre Habilidades (K) → Macro y añade teclas completas como pasos, con 10 ms de retraso (40-50 ms si tienes mucho ping).", en: "Open Skills (K) → Macro and add whole keys as steps, 10 ms delay each (40–50 ms on high ping).", fr: "Abre Compétences (K) → Macro et añade teclas completas como pasos, avec 10 ms de retraso (40-50 ms si as mucho ping).", de: "Open Skills (K) → Makro und ganze Tasten als Schritte hinzufügen, jeweils 10 ms verzögern (40-50 ms auf hohem Ping).", pt: "Habilidades abertas (K) → Macro e adicionar chaves inteiras como passos, 10 ms atraso cada (40-50 ms em ping alto).", ru: "Откройте Skills (K) → Macro и добавьте целые клавиши в качестве шагов, 10 мс задерживайте каждый (40-50 мс на высоком пинге).", ko: "오픈 스킬 (K) → 매크로를 추가하고 단계로 전체 키를 추가, 10 ms 지연 각 (40-50 ms에서 높은 핑).", ja: "スキル(K)→マクロを開き、ステップとしてキー全体を追加し、各10msの遅延(40〜50ms)。" },
  "barra.paso4": { es: "Cada uno de los 3 presets guarda sus niveles, estigmas y su macro (Alt + Num 4/5/6).", en: "Each of the 3 presets keeps its own levels, stigmas and macro (Alt + Num 4/5/6).", fr: "Cada uno des 3 presets guarda ses niveles, estigmas et son macro (Alt + Num 4/5/6).", de: "Jeder der 3 Presets behält seine eigenen Ebenen, Stigmata und Makro (Alt + Num 4/5/6).", pt: "Cada uma das 3 predefinições mantém seus próprios níveis, estigmas e macro (Alt + Num 4/5/6).", ru: "Каждый из 3 предустановок сохраняет свои уровни, стигмы и макрос (Alt + Num 4/5/6).", ko: "3개의 미리 세트의 각각은 그것의 자신의 수준, stigmas 및 매크로 (Alt + Num 4/5/6)를 지킵니다.", ja: "それぞれの3プリセットは、独自のレベル、スティグマ、マクロ(Alt + Num 4/5/6)を保持します。" },
  "barra.paso5": { es: "Deja fuera de la macro los buffs, defensivas, desplazamientos y habilidades cargadas. Usa el modo de control AION 2.", en: "Keep buffs, defensives, dashes and charged skills out of the macro. Use the AION 2 control mode.", fr: "Deja fuera de la macro los buffs, defensivas, desplazamientos et habilidades cargadas. Usa el modo de contrôle AION 2.", de: "Halten Sie Buffs, Defensive, Striche und aufgeladene Fähigkeiten aus dem Makro. Verwenden Sie den AION 2-Steuermodus.", pt: "Mantenha os fãs, defensivos, traços e habilidades carregadas fora da macro. Use o modo de controle AION 2.", ru: "Держите баффов, защитные силы, тире и заряженные навыки вне макроса. Используйте режим управления AION 2.", ko: "버프를 유지, 방어, dashes 및 충전 기술 매크로에서. AION 2 제어 모드를 사용하십시오.", ja: "マクロからバフ、防御力、ダッシュ、チャージスキルを保ちます。 AION 2 制御モードを使用します。" },
  "barra.fuentes": { es: "Según las guías de", en: "Based on the guides from", fr: "Based sur le Guides de", de: "Basierend auf den Guides von", pt: "Baseado nos guias de", ru: "Основываясь на путеводителях", ko: "자주 묻는 질문", ja: "ガイドに基づく" },
  "legado.solo_es": { es: "Esta guía de referencia solo está disponible en español por ahora.", en: "This reference guide is only available in Spanish for now.", fr: "Ce reference guide is only available dans Spanish pour maintenant.", de: "Diese Referenzanleitung ist vorerst nur auf Spanisch verfügbar.", pt: "Este guia de referência só está disponível em espanhol por enquanto.", ru: "На данный момент это справочное руководство доступно только на испанском языке.", ko: "이 참조 가이드는 스페인어에서만 사용할 수 있습니다.", ja: "この参考ガイドは、スペイン語でのみ利用可能です。" },
  "legado.ref_titulo": { es: "Guía de referencia de la clase", en: "Class reference guide", fr: "Classe reference guide", de: "Klassenreferenzleitfaden", pt: "Guia de referência da classe", ru: "Руководство по классу", ko: "Class 참고 가이드", ja: "クラス参照ガイド" },
