  "legado.abrir_build": { es: "Abrir como build (copiar a mis builds)", en: "Open as a build (copy to my builds)", fr: "Ouvrir como build (copiar a mis builds)", de: "Open as a Build (Kopie auf meine Builds)", pt: "Abrir como uma construção (cópia para as minhas construções)", ru: "Открытый как сборка (копия для моих сборок)", ko: "빌드로 열기 (내 빌드에 복사)", ja: "ビルドとして開く(ビルドへのコピー)" },
