  "mis.importar_sub": { es: "Busca tu personaje. Se crea una copia editable con habilidades y Daevanion actuales; la ficha del juego no se toca.", en: "Search your character. An editable copy is created with current skills and Daevanion; the live profile is left alone.", fr: "Rechercher votre personnage. An Modifierable copy is created avec current Compétences et Daevanion; le live profil is left alone.", de: "Suche deinen Charakter. Eine editierbare Kopie wird mit aktuellen Fähigkeiten und Daevanion erstellt; das Live-Profil wird in Ruhe gelassen.", pt: "Revista o teu carácter. Uma cópia editável é criada com habilidades atuais e Daevanion; o perfil ao vivo é deixado sozinho.", ru: "Ищите своего персонажа. Редактируемая копия создается с текущими навыками и Daevanion; живой профиль оставлен в покое.", ko: "문자를 검색합니다. 편집 가능한 복사본은 현재 기술과 대반으로 만들어졌습니다. 라이브 프로파일은 혼자 남아 있습니다.", ja: "キャラクターを探す 編集可能なコピーは、現在のスキルとデバニオンで作成され、ライブプロファイルは単独で残されます。" },
  "mis.buscar": { es: "Buscar", en: "Search", fr: "Rechercher", de: "Suchen", pt: "Pesquisar", ru: "Поиск", ko: "검색", ja: "検索" },
  "mis.importar_btn": { es: "Crear copia", en: "Create copy", fr: "Créer copy", de: "Erstellen Sie eine Kopie", pt: "Criar cópia", ru: "Создать копию", ko: "비밀번호", ja: "コピーの作成" },
  "mis.importando": { es: "Importando…", en: "Importing…", fr: "Importando…", de: "Importieren...", pt: "Importando...", ru: "Импортировать...", ko: "수입 ...", ja: "インポート..." },
  "mis.personajes": { es: "Tus personajes del juego", en: "Your in-game characters", fr: "Votre dans-Jeu personnages", de: "Deine In-Game-Charaktere", pt: "Seus personagens no jogo", ru: "Ваши игровые персонажи", ko: "게임 내 캐릭터", ja: "ゲーム内キャラクター" },
  "mis.personajes_sub": { es: "Ya vinculados a tu cuenta. Ver abre la ficha en caché; Nueva copia crea una build editable.", en: "Already linked to your account. View opens the cached profile; New copy creates an editable build.", fr: "Already linked à votre Compte. Voir Ouvrirs le cached profil; Nouveau copy creates an Modifierable build.", de: "Sie sind bereits mit Ihrem Konto verknüpft. View öffnet das zwischengespeicherte Profil; Neue Kopie erstellt einen editierbaren Build.", pt: "Já está ligado à sua conta. Ver abre o perfil em cache; Nova cópia cria uma compilação editável.", ru: "Уже привязан к вашему аккаунту. Вид открывает кэшированный профиль; Новая копия создает редактируемую сборку.", ko: "귀하의 계정에 연결된 이미. 새로운 복사본은 편집 가능한 빌드를 만듭니다.", ja: "すでにアカウントにリンクされています。 キャッシュされたプロファイルを開きます。新しいコピーは編集可能なビルドを作成します。" },
  "mis.nueva_copia": { es: "Nueva copia", en: "New copy", fr: "Nueva copia", de: "Neue Kopie", pt: "Nova cópia", ru: "Новая копия", ko: "새 사본", ja: "新しいコピー" },
