  "juego.actualizando": { es: "Actualizando ficha del juego… 30–60 s", en: "Updating in-game profile… 30–60 s", fr: "Updating dans-Jeu profil… 30–60 s", de: "Aktualisieren des In-Game-Profils ... 30-60 s", pt: "Actualizando o perfil no jogo... 30–60 s", ru: "Обновление игрового профиля... 30-60 с", ko: "게임 프로필 업데이트... 30–60 s", ja: "ゲーム内プロファイルの更新... 30〜60秒" },
