  "juego.json_bonus": { es: "Mapa solo de Daevanion, por id de habilidad. Ya está volcado en habilidades[].daevanion.", en: "Daevanion-only map, by skill id. Already copied into habilidades[].daevanion.", fr: "Carte seulement de Daevanion, por id de habilidad. Ya est volcado en habilidades[].daevanion.", de: "Daevanion-only Karte, nach Skill ID. Bereits kopiert in habilidades[].daevanion.", pt: "Mapa só de Daevanion, por habilidade. Já copiado para habilidades[].daevanion.", ru: "Карта Дэваниона только по навыкам. Уже скопирован в habilidades[].daevanion.", ko: "Daevanion-only 지도, 기술 ID. Already는 habilidades[].daevanion에 복사했습니다.", ja: "Daevanion-onlyのマップ、スキルIDによる。 すでにhabilidades[].daevanionにコピーしました。" },
  "juego.json_bonus_eq": { es: "Mapa solo del equipo, por id de habilidad. Ya está volcado en habilidades[].armadura.", en: "Gear-only map, by skill id. Already copied into habilidades[].armadura.", fr: "Carte seulement du equipo, por id de habilidad. Ya est volcado en habilidades[].armadura.", de: "Gear-only Karte, nach Skill ID. Bereits kopiert in habilidades[].armadura.", pt: "Mapa só de artes, por identificação de habilidade. Já copiado para habilidades.armadura.", ru: "Карта только с помощью перьев. Уже скопированы в habilidades[].armadura.", ko: "Gear-only 맵, 기술 ID로. 이미 habilidades[].armadura에 복사.", ja: "ギア専用のマップ、スキルIDで。 すでにhabilidades[].armaduraにコピーしました。" },
  "juego.json_copiado": { es: "JSON NC copiado al portapapeles", en: "NC JSON copied to clipboard", fr: "JSON NC copiado au portapapeles", de: "NC JSON kopiert ins Clipboard", pt: "NC JSON copiado para a área de transferência", ru: "NC JSON скопировали в буфер обмена", ko: "NC JSON은 클립보드에 복사", ja: "NC JSONがクリップボードにコピー" },
  "juego.json_descargado": { es: "JSON NC descargado", en: "NC JSON downloaded", fr: "JSON NC descargado", de: "NC JSON heruntergeladen", pt: "NC JSON baixado", ru: "NC JSON скачать", ko: "NC JSON 다운로드", ja: "NC JSONのダウンロード" },
