  "juego.ver": { es: "Ver build del juego", en: "View in-game build", fr: "Voir dans-Jeu build", de: "In-Game Build ansehen", pt: "Ver a compilação no jogo", ru: "Вид внутриигровой сборки", ko: "게임 빌드", ja: "ゲーム内ビルドを見る" },
