  "juego.elige_lado": { es: "Elige con qué comparar.", en: "Choose what to compare with.", fr: "Choisir what à compare avec.", de: "Wählen Sie aus, mit was Sie vergleichen möchten.", pt: "Escolha com o que comparar.", ru: "Выберите, с чем сравнивать.", ko: "비교할 것을 선택하십시오.", ja: "比較するものを選択します。" },
  "juego.pasando": { es: "Si pasaras de {a} a {b}:", en: "If you went from {a} to {b}:", fr: "If you went from {a} to {b}:", de: "Wenn du von {a} nach {b} gegangen bist:", pt: "Se passou de {a} para {b}:", ru: "Если вы перешли от {a} к {b}:", ko: "{a}에서 {b}로 갔다면:", ja: "{a} から {b} へ行った場合:" },
