  "juego.frase_cmp_hab": { es: "{mas} habilidades subirían y {menos} bajarían.", en: "{mas} skills would go up and {menos} down.", fr: "{mas} skills would go up and {menos} down.", de: "{mas} Fähigkeiten würden steigen und {menos} nach unten gehen.", pt: "As habilidades subiriam e menos desceriam.", ru: "Навыки будут идти вверх и вниз.", ko: "{mas} 기술이 올라가고 {menos} 아래로.", ja: "{mas} のスキルが上がり、{menos} がダウンします。" },
