  "err.nombre_vacio": { es: "Ponle un nombre a la build.", en: "Give the build a name.", fr: "Give le build a Nom.", de: "Geben Sie dem Build einen Namen.", pt: "Dê um nome ao edifício.", ru: "Дайте зданию имя.", ko: "이름 만들기.", ja: "ビルド名を指定します。" },
