  "err.sin_permiso": { es: "No tienes permiso para hacer eso.", en: "You don't have permission to do that.", fr: "Vous don't have permission à do cela.", de: "Sie haben keine Erlaubnis, das zu tun.", pt: "Não tens permissão para fazer isso.", ru: "У тебя нет на это разрешения.", ko: "당신은 그것을 할 권한이 없습니다.", ja: "これを行う許可はありません。" },
