  "err.generico": { es: "Algo ha fallado. Inténtalo de nuevo.", en: "Something went wrong. Try again.", fr: "Algo ha faulado. Inténtauo de nouveau.", de: "Irgendetwas ging schief. Versuchen Sie es noch einmal.", pt: "Algo correu mal. Tenta outra vez.", ru: "Что-то пошло не так. Попробуй снова.", ko: "뭔가 잘못되었습니다. 다시 시도하십시오.", ja: "何かが間違っていた。 もう一度お試しください。" },

