  "super.titulo": { es: "Panel superadmin", en: "Superadmin panel", fr: "Panel sonperadmin", de: "Superadmin-Panel", pt: "Painel de super administração", ru: "Панель Superadmin", ko: "Superadmin 패널", ja: "スーパーadminパネル" },
  "super.sub": { es: "Roles, Discord, visitas y reglas del bot. Un compañero en el Panel de moderación no ve esto.", en: "Roles, Discord, visits and bot rules. Someone on the mod Panel won't see this.", fr: "Roles, Discord, visitas et reglas du bot. Un compañero en el Panel de moderación ne ve esto.", de: "Rollen, discord, besuche und bot-regeln. Jemand auf dem mod Panel wird das nicht sehen.", pt: "Funções, Discórdia, visitas e regras bot. Alguém no painel mod não vai ver isto.", ru: "Роли, разногласия, посещения и правила бота. Кто-то на панели модов этого не увидит.", ko: "역할, Discord, 방문 및 봇 규칙. mod 패널의 누군가가 이것을 볼 수 없습니다.", ja: "役割、記録解除、訪問およびボット規則。 mod パネルの誰かがこれを見ることができません。" },
  "super.ir_panel": { es: "Ir al Panel de moderación", en: "Go to moderation Panel", fr: "Ir au Panel de moderación", de: "Gehen Sie zum Moderation Panel", pt: "Ir para painel de moderação", ru: "Перейдите в панель модерации", ko: "회사연혁", ja: "モデレーションパネルに行く" },
  "super.visitas": { es: "Tráfico", en: "Traffic", fr: "Tráfico", de: "Verkehr", pt: "Tráfego", ru: "Трафик", ko: "관련 기사", ja: "交通アクセス" },
  "super.visitas_txt": { es: "Entradas a la web (escaparate y principal). Útiles para medir audiencia antes de publicidad. Un mismo visitante no cuenta más de una vez cada 30 minutos por página.", en: "Site entries (showcase and main). Useful to gauge audience before ads. The same visitor isn't counted more than once every 30 minutes per page.", fr: "Entradas a la web (escapourte et principau). Útiles pour medir audiencia avant de publicidad. Un mismo visitante ne cuenta plus de una vez chaque 30 minutos por página.", de: "Site-Einträge (Showcase und Main). Nützlich, um das publikum vor anzeigen zu messen. Der gleiche Besucher wird nicht mehr als einmal alle 30 Minuten pro Seite gezählt.", pt: "Entradas do site (showcase e main). Útil para avaliar o público antes dos anúncios. O mesmo visitante não é contado mais de uma vez a cada 30 minutos por página.", ru: "Записи на сайте (демонстрационный и основной). Полезно оценить аудиторию перед рекламой. Один и тот же посетитель засчитывается не чаще одного раза в 30 минут на страницу.", ko: "사이트 항목 (showcase 및 main). 광고 전에 청중을 측정하는 것이 유용합니다. 동일한 방문자는 페이지 당 30 분마다 한 번 이상 계산되지 않습니다.", ja: "サイトエントリ(ショーケースとメイン)。 広告の前に聴衆を測るのに有用。 同一の訪問者は、1ページにつき30分以上カウントされません。" },
  "super.visitas_total": { es: "Visitas totales", en: "Total visits", fr: "Visitas totaues", de: "Besuche insgesamt", pt: "Total das visitas", ru: "Всего посещений", ko: "총 방문", ja: "トータルアクセス" },
  "super.visitas_unicos": { es: "Únicos (suma diaria)", en: "Uniques (daily sum)", fr: "Uniques (quotidien sum)", de: "Uniques (tägliche Summe)", pt: "Exclusivos (soma diária)", ru: "Ежедневная сумма (Daily sum)", ko: "Uniques (매일 합계)", ja: "ユニーク(デイリー合計)" },
