  "panel.juego_txt": { es: "Lo que la web ha detectado en la web oficial y conviene revisar.", en: "What the site picked up from the official site and is worth a look.", fr: "Lo que la web ha detectado en la web officiel et avecviene revisar.", de: "Was die Website von der offiziellen Website abgeholt hat und ist einen Blick wert.", pt: "O que o site pegou do site oficial e vale a pena uma olhada.", ru: "Что сайт подобрал с официального сайта и стоит посмотреть.", ko: "공식 사이트에서 픽업되는 사이트와 살펴볼 가치가 있습니다.", ja: "公式サイトからピックアップされたサイトは、一見の価値ありです。" },
  "panel.hab_nuevas": { es: "habilidades que la web aún no conoce", en: "skills the site does not know yet", fr: "Compétences le site does pas kmaintenant yet", de: "Fähigkeiten, die die Website noch nicht kennt", pt: "habilidades que o site ainda não sabe", ru: "Навыки, которые сайт еще не знает", ko: "사이트가 아직 알 수 없습니다.", ja: "サイトのスキルはまだわからない" },
  "panel.discord_txt": { es: "Cuando tengáis el servidor, pon aquí el ID y la invitación. Mientras esté vacío, no se ve nada en la web.", en: "Once you have the server, paste its ID and invite here. While empty, nothing shows on the site.", fr: "Cuando tengáis el serveur, pon ici el ID et la invitación. Mientras esté vacío, ne se ve nada en la web.", de: "Sobald Sie den Server haben, fügen Sie seine ID ein und laden Sie hier ein. Während leer, nichts zeigt auf der Website.", pt: "Depois de ter o servidor, cole seu ID e convide aqui. Enquanto vazio, nada aparece no site.", ru: "После того, как у вас есть сервер, вставьте его идентификатор и пригласите сюда. Пока пусто, на сайте ничего не видно.", ko: "서버가 있으면 ID를 풀고 여기에 초대합니다. 비어있는 동안, 아무것도 사이트에 보여줍니다.", ja: "サーバをお持ちでしたら、IDを貼り付けて招待してください。 空の間、サイトに何も表示しません。" },
  "panel.discord_id": { es: "ID del servidor", en: "Server ID", fr: "Serveur ID", de: "Server-ID", pt: "ID do servidor", ru: "Серверный идентификатор", ko: "서버 ID", ja: "サーバーID" },
