  "foro.desc_presentaciones": { es: "Di hola: quién eres, qué clase juegas, a qué hora sueles entrar.", en: "Say hi: who you are, what you play, when you are usually on.", fr: "Di hola: quién eres, qué clase juegas, a qué hora soneles entrar.", de: "Sag hallo: wer du bist, was du spielst, wenn du normalerweise an bist.", pt: "Diga oi: quem você é, o que você toca, quando você está geralmente em.", ru: "Скажи привет: кто ты, во что ты играешь, когда ты обычно находишься.", ko: "안녕하세요 : 누구인지, 당신이 연주하는 것, 당신은 일반적으로있을 때.", ja: "あなたがいる人、あなたが遊ぶもの、あなたが通常オンにいるとき。" },
  "foro.desc_clases": { es: "Dudas y trucos de cada clase.", en: "Questions and tips for each class.", fr: "Dudas et trucos de chaque clase.", de: "Fragen und Tipps für jede Klasse.", pt: "Perguntas e dicas para cada classe.", ru: "Вопросы и советы для каждого класса.", ko: "각 클래스의 질문과 팁.", ja: "各クラスの質問とヒント。" },
  "foro.desc_builds": { es: "Enseña tu build y pide opinión. Pega el enlace y sale la tarjeta.", en: "Show your build and ask for feedback. Paste the link and the card appears.", fr: "Afficher votre build et ask pour feedRetour. Paste le link et le card appears.", de: "Zeigen Sie Ihren Build und bitten Sie um Feedback. Fügen Sie den Link und die Karte erscheint.", pt: "Mostre a sua compilação e peça feedback. Colar o link e o cartão aparece.", ru: "Покажите свою сборку и попросите обратную связь. Вставьте ссылку, и карта появится.", ko: "빌드를 표시하고 피드백을 요청합니다. 링크와 카드가 나타납니다.", ja: "あなたのビルドを表示し、フィードバックを尋ねます。 リンクを貼り付け、カードが表示されます。" },
  "foro.desc_grupos": { es: "Mazmorras, jefes y quedadas.", en: "Dungeons, bosses and meetups.", fr: "Mazmorras, jefes et quedadas.", de: "Dungeons, Chefs und Meetups.", pt: "Dungeons, chefes e encontros.", ru: "Подземелья, боссы и встречи.", ko: "Dungeons, 보스 및 meetups.", ja: "ダンジョン、ボス、ミートアップ。" },
  "foro.desc_reclutamiento": { es: "Buscas o ofreces legión. Publica requisitos aquí.", en: "Looking for or recruiting a legion. Post requirements here.", fr: "Buscas ou ofreces legión. Publica requisitos ici.", de: "Suche oder Rekrutierung einer Legion. Post Anforderungen hier.", pt: "Procurando ou recrutando uma legião. Exigências de postagem aqui.", ru: "Ищу или набираю легион. Требования к почте здесь.", ko: "법률을 찾고 또는 모집. 여기에 포스트 요구 사항.", ja: "レギオンを探し、または採用します。 ここに条件を掲示して下さい。" },
