  "mis.borrar_titulo": { es: "Borrar mi cuenta", en: "Delete my account", fr: "Supprimer my Compte", de: "Lösche meinen Account", pt: "Apagar a minha conta", ru: "Удалить мой аккаунт", ko: "내 계정 삭제", ja: "アカウントを削除" },
  "mis.borrar_aviso": {
    es: "Esto es irreversible. Se eliminan tu usuario, builds, personajes vinculados, votos y notificaciones.",
    en: "This cannot be undone. Your username, builds, linked characters, votes and notifications are removed.", fr: "Ce cannot be undone. Votre Nom d’utilisateur, Builds, linked personnages, votes et notifications are Retirerd.", de: "Dies kann nicht rückgängig gemacht werden. Ihr Benutzername, Builds, verknüpfte Zeichen, Stimmen und Benachrichtigungen werden entfernt.", pt: "Isto não pode ser desfeito. Seu nome de usuário, builds, caracteres vinculados, votos e notificações são removidos.", ru: "Это нельзя отменить. Ваше имя пользователя, сборки, связанные символы, голоса и уведомления удаляются.", ko: "이것은 undone일 수 없습니다. 사용자 이름, 빌드, 링크 된 문자, 투표 및 알림이 제거됩니다.", ja: "これは元に戻すことができません。 ユーザー名、ビルド、リンクされた文字、投票、通知は削除されます。"
  },
  "mis.borrar_li1": {
    es: "Mensajes del foro se anonimizan («Cuenta eliminada») para no romper hilos ajenos.",
    en: "Forum posts are anonymized (“Deleted account”) so other threads stay readable.", fr: "Forum posts are aNonnymized (“Supprimerd Compte”) so other threads stay readable.", de: "Forenbeiträge werden anonymisiert („gelöschtes Konto), sodass andere Threads lesbar bleiben.", pt: "Os posts do fórum são anônimos (“conta apagada”) para que outros threads permaneçam legíveis.", ru: "Посты форума анонимизируются («Удаленный аккаунт»), поэтому другие потоки остаются читаемыми.", ko: "포럼 게시물은 익명화 (\"Deleted account\")이므로 다른 스레드는 읽기 할 수 있습니다.", ja: "フォーラム投稿は匿名化(「削除されたアカウント」)なので、他のスレッドは読みやすくなります。"
  },
  "mis.borrar_li2": {
    es: "El chat reciente de tu cuenta se borra.",
    en: "Your recent chat messages are deleted.", fr: "Votre recent Chat messages are Supprimerd.", de: "Ihre letzten chat-nachrichten werden gelöscht.", pt: "Suas mensagens de chat recentes são apagadas.", ru: "Ваши последние сообщения в чате удаляются.", ko: "최근 채팅 메시지가 삭제됩니다.", ja: "最近のチャットメッセージが削除されます。"
  },
  "mis.borrar_li3": {
    es: "No pedimos email: con borrar la cuenta basta para ejercer el derecho de supresión.",
    en: "We don’t ask for email: deleting the account is enough to exercise the right to erasure.", fr: "We don’t ask pour e-mail: deleting le Compte is eNonugh à exercise le right à erasure.", de: "Wir bitten nicht um E-Mail: Das Löschen des Kontos reicht aus, um das Recht auf Löschung auszuüben.", pt: "Não pedimos e-mail: excluir a conta é suficiente para exercer o direito de apagar.", ru: "Мы не запрашиваем электронную почту: удаления учетной записи достаточно, чтобы воспользоваться правом на удаление.", ko: "우리는 이메일을 요청하지 않습니다 : 계정을 삭제하는 것은 지우기 위해 적절한 조치를 취할 충분합니다.", ja: "メールでのお問い合わせ: 退会は、消去の権利を行使するのに十分です。"
  },
